-- Španělské názvy a popisy surovin pro katalog na webu (/es/suroviny).
-- Přeloženo z českých řádků food_translations; appka sama je nevyrábí,
-- nová surovina v appce spadne na webu na angličtinu (viz src/lib/foods.ts).
-- Idempotentní: řádek se vloží jen tam, kde španělský překlad ještě není.

insert into public.food_translations (food_id, locale, name, description)
select v.food_id::uuid, 'es', v.name, v.description
from (values
  ('29309265-98fe-48df-ab2b-cf366109d04a', $t$Anchoas (boquerones)$t$, $t$Anchoas (boquerones): pequeños pescados azules ricos en omega-3 y calcio (se comen enteros). Usar frescos o congelados, no en salazón. Pescado azul de mar, valiosa fuente de omega-3 y vitamina D. Incluir 1–2 veces por semana.$t$),
  ('a0000006-0000-0000-0000-000000000003', $t$Plátano$t$, $t$Plátano: fruta dulce rica en potasio. Cantidades muy pequeñas. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('c689b537-46e6-45e2-9afc-a310893e6d7c', $t$Boniato$t$, $t$Boniato: fuente de fibra y betacaroteno. Servir cocinado. Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('6051e9b5-863b-4631-8ad4-3e5dda636b4c', $t$Yogur natural$t$, $t$Yogur natural: probióticos y calcio. Pequeñas cantidades. Complemento lácteo: solo en pequeñas cantidades, algunos perros toleran mal la lactosa. Fuente de proteínas y calcio.$t$),
  ('a0000006-0000-0000-0000-000000000002', $t$Arándanos$t$, $t$Arándanos: antioxidantes, premio pequeño ideal. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('a0000005-0000-0000-0000-000000000002', $t$Brócoli$t$, $t$Brócoli: crucífera con vitamina C. Solo pequeñas cantidades. Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('fb1b6b73-6cf9-4060-85bc-f747d54d384a', $t$Apio$t$, $t$Apio: verdura jugosa y baja en calorías con fibra. Picar fino o triturar (tallos fibrosos). Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('76ebab08-3cc8-4db3-af20-febdb22d4b50', $t$Grosella negra$t$, $t$Grosella negra: bayas oscuras con un contenido excepcionalmente alto de vitamina C. Ribes, no uvas: segura en pequeñas cantidades. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('6f014bae-e624-452e-a44e-c19e35e86d05', $t$Grosella roja$t$, $t$Grosella roja: bayas ácidas ricas en vitamina C y fibra. La grosella (Ribes) no es uva; para los perros es segura en pequeñas cantidades. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('a0000005-0000-0000-0000-000000000003', $t$Calabacín$t$, $t$Calabacín: verdura ligera, fácil de digerir y baja en calorías. Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('0c85323f-f4b7-420d-aeee-f5075540d621', $t$Carne de gamo$t$, $t$Carne de gamo: caza magra. Base de la ración: constituye el 50–70 % de la parte cárnica. Si la caza no procede de una fuente verificada (p. ej. del supermercado), mejor cocerla.$t$),
  ('702a5427-731f-4730-8f64-7efd6289ac10', $t$Jabalí$t$, $t$Jabalí: carne de caza oscura. Congelar por la enfermedad de Aujeszky y las triquinas. Base de la ración: constituye el 50–70 % de la parte cárnica. Si la caza no procede de una fuente verificada (p. ej. del supermercado), mejor cocerla.$t$),
  ('16d2ff5e-eadc-4bfd-ad6b-081e7b14cc9a', $t$Calabaza$t$, $t$Calabaza: fibra suave, favorece la digestión. Servir cocida. Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('19aea7c3-4afb-4e44-9713-577739581ec8', $t$Callos de vacuno$t$, $t$Callos de vacuno: la panza verde sin lavar favorece la digestión y el microbioma. Estómago (callos): verde y sin lavar es excelente para la digestión y el microbioma. Cuenta como carne muscular.$t$),
  ('a0000004-0000-0000-0000-000000000002', $t$Hígado de vacuno$t$, $t$Hígado de vacuno: la fuente de hígado clásica y más habitual en el BARF. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('e1b1a750-4fbf-4aae-9268-48e42b6799b6', $t$Lengua de vacuno$t$, $t$Lengua de vacuno: carne muscular más grasa, cuenta como carne. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('a0000003-0000-0000-0000-000000000003', $t$Riñones de vacuno$t$, $t$Riñones de vacuno: órgano secretor rico en selenio y vitaminas B. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('d5b54d70-b04c-4e41-b3f8-e6cf43a8b0a8', $t$Carrilleras de vacuno$t$, $t$Carrilleras de vacuno: músculo de trabajo, magro y jugoso. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('dfe72b7d-72a0-46b2-a91e-9363997b2a49', $t$Hueso de caña de vacuno$t$, $t$Hueso de caña de vacuno: hueso de carga muy duro, solo para roer. Hueso de carga más duro: más para roer que para comer. SIEMPRE crudo, vigila el desgaste dental.$t$),
  ('1395dd80-e114-4772-af5b-27900c91b465', $t$Sesos de vacuno$t$, $t$Sesos de vacuno: fuente de grasas saludables y DHA. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('f3249739-7cd5-4a86-a39d-f724e019a0e6', $t$Rabo de vacuno$t$, $t$Rabo de vacuno: hueso carnoso con cartílago, fuente de colágeno. Hueso de carga más duro: más para roer que para comer. SIEMPRE crudo, vigila el desgaste dental.$t$),
  ('a0000003-0000-0000-0000-000000000004', $t$Pulmón de vacuno$t$, $t$Pulmón de vacuno: órgano ligero y bajo en grasa. Dar como complemento de la parte cárnica; también es popular deshidratado como premio.$t$),
  ('aaf196f4-c2ea-4251-bf7a-a286ed463234', $t$Tráquea de vacuno$t$, $t$Tráquea de vacuno: cartílago con glucosamina, excelente premio masticable. Parte cartilaginosa: fuente natural de glucosamina y condroitina para las articulaciones. Premio masticable muy popular.$t$),
  ('9acb18fb-345e-4b90-9dfa-1572ee0d4c80', $t$Bazo de vacuno$t$, $t$Bazo de vacuno: órgano secretor muy rico en hierro. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('3f9c2160-688e-4799-8c46-e968d7098af8', $t$Páncreas de vacuno$t$, $t$Páncreas de vacuno: órgano secretor, enzimas naturales (adecuado en caso de IPE). Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('a0000003-0000-0000-0000-000000000002', $t$Corazón de vacuno$t$, $t$Corazón de vacuno: excelente fuente de taurina, asequible. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('a0000001-0000-0000-0000-000000000002', $t$Carne muscular de vacuno$t$, $t$Carne muscular de vacuno: la carne magra básica de la ración BARF. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('56778459-2e46-48e7-bc0b-9c66363f028a', $t$Ubre de vacuno$t$, $t$Ubre de vacuno: carne muscular complementaria grasa. Cuenta como carne muscular, no como víscera: no tiene vitamina A, cobre ni selenio como el hígado o los riñones. Poca proteína y mucha grasa, así que solo para variar: no sustituye a la carne de vacuno.$t$),
  ('45ce601b-9401-40c7-bbce-cd0e0be3e84e', $t$Pera$t$, $t$Pera: fruta jugosa con fibra. Sin el corazón. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('adfbf92d-ab6a-4667-8bbb-c4f11c9456d1', $t$Hígado de oca$t$, $t$Hígado de oca: graso y rico, solo en pequeñas cantidades. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('50cd76c8-593c-4209-adf0-288ddacdc443', $t$Cuellos de oca$t$, $t$Cuellos de oca: hueso comestible grande y más graso. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('1ac34fa5-d58e-4174-8e68-4d60bd04719a', $t$Carne de oca$t$, $t$Carne de oca: ave más grasa, sabor intenso. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('a0000006-0000-0000-0000-000000000001', $t$Manzana$t$, $t$Manzana: fuente de fibra y vitamina C. Quitar el corazón (las pepitas contienen cianuro). Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('2bf512d2-fe48-40b4-a185-3148bbf4b741', $t$Fresas$t$, $t$Fresas: vitamina C y fibra, como premio. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('7164342c-b939-45eb-b9aa-871d02c062e8', $t$Hígado de cordero$t$, $t$Hígado de cordero: rico en cobre y vitamina A. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('d35ddd87-a7b9-43cf-9455-3ab48b9c9ee6', $t$Lengua de cordero$t$, $t$Lengua de cordero: carne muscular más grasa. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('ee19cd47-c739-4e64-a446-b33795e3d842', $t$Riñones de cordero$t$, $t$Riñones de cordero: riñones más pequeños y delicados. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('a0000001-0000-0000-0000-000000000004', $t$Carne de cordero$t$, $t$Carne de cordero: carne roja más grasa y de sabor marcado. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('07e8641d-d73b-44d1-b437-057fbde6e71b', $t$Pulmón de cordero$t$, $t$Pulmón de cordero: órgano ligero, popular como premio deshidratado. Órgano ligero y bajo en grasa. Dar como complemento de la parte cárnica; también es popular deshidratado como premio.$t$),
  ('f925dca9-49b2-4c90-a1a9-ed4fb158c7bd', $t$Corazón de cordero$t$, $t$Corazón de cordero: corazón más pequeño, ideal para perros medianos. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('3c87d0ca-fee4-45ac-853a-bc90a308dcef', $t$Costillas de cordero$t$, $t$Costillas de cordero: hueso comestible con una capa de carne y grasa. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('fc9b60eb-dc25-43c2-bae7-6e5502792888', $t$Hígado de ciervo$t$, $t$Hígado de ciervo: hígado de caza, rico en nutrientes. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('ed329b3b-fb4e-41cb-b303-1da314174fc4', $t$Hígado de pato$t$, $t$Hígado de pato: hígado de ave más graso. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('c74f3c78-af49-48a4-9eee-590b7eacc587', $t$Alas de pato$t$, $t$Alas de pato: hueso comestible carnoso. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000002-0000-0000-0000-000000000003', $t$Cuellos de pato$t$, $t$Cuellos de pato: hueso comestible más grande para perros medianos y grandes. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000001-0000-0000-0000-000000000005', $t$Pechuga de pato$t$, $t$Pechuga de pato: carne de ave oscura más magra. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('a4f6cd41-cea7-4fa5-adfc-3b11c0b64dc0', $t$Carcasas de pato$t$, $t$Carcasas de pato: esqueleto más graso con cartílago. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('2e3cc505-ceb6-4c91-87c7-efbaba617d87', $t$Corazones de pato$t$, $t$Corazones de pato: pequeño órgano muscular con taurina. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('53361084-adb1-43de-8ac2-ac73025ccd1c', $t$Mollejas de pato$t$, $t$Mollejas de pato: musculosas y sabrosas. Molleja musculosa, cuenta como carne muscular. Naturalmente rica en proteínas.$t$),
  ('8a817089-1223-4042-8ea3-e01e0e265b78', $t$Hígado de caballo$t$, $t$Hígado de caballo: magro y rico en hierro. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('e36871a2-7e20-4c68-90d9-0df96ec31118', $t$Carne de caballo$t$, $t$Carne de caballo: magra, hipoalergénica, adecuada en caso de alergias. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('f81d67a3-a49e-49f3-af72-27ee577c3ed0', $t$Corazón de caballo$t$, $t$Corazón de caballo: órgano muscular magro. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('1f48fd0f-78a3-4091-8c7b-49e39bc39c3c', $t$Carne de cabra$t$, $t$Carne de cabra: carne roja magra, poco alergénica. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('0236d8aa-8504-4618-94ea-a37b83a6a572', $t$Hígado de conejo$t$, $t$Hígado de conejo: hígado magro de una carne magra. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('1ef4deb1-21c7-44a0-9215-8d6350bf5d6b', $t$Carne de conejo$t$, $t$Carne de conejo: magra y fácil de digerir, hipoalergénica. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('53081f21-372e-44e9-87bb-d933f5f475e1', $t$Conejo entero (con hueso)$t$, $t$Conejo entero con hueso: presa completa, carne muscular, huesos comestibles y vísceras juntos. La app lo reparte aproximadamente en un 60 % de carne muscular, un 30 % de huesos y un 10 % de vísceras. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('dc010526-9f58-49cb-8ff1-adb082496379', $t$Codorniz (entera)$t$, $t$Codorniz entera: presa pequeña completa, con huesos y órganos. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('20e99202-683d-4dce-97ce-7e29b616f3e1', $t$Hígado de pavo$t$, $t$Hígado de pavo: fuente de hígado de ave. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('68f7535a-d943-4647-92b2-ae4116ca009f', $t$Alas de pavo$t$, $t$Alas de pavo: hueso comestible carnoso para perros más grandes. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('c4e9cc16-dd6a-4fef-b83e-2bcf2a6cf127', $t$Cuellos de pavo$t$, $t$Cuellos de pavo: hueso comestible grande para perros grandes. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000001-0000-0000-0000-000000000003', $t$Pechuga de pavo$t$, $t$Pechuga de pavo: carne blanca muy magra. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('c416d378-17da-493a-a961-4346c65ca704', $t$Corazón de pavo$t$, $t$Corazón de pavo: órgano muscular rico en taurina. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('45c82f5d-99ad-4f15-b714-2ba229bf308d', $t$Muslo de pavo$t$, $t$Muslo de pavo: carne más oscura y algo más grasa. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('8c2ad4ff-590b-49d4-ad24-00c4ddf6425c', $t$Mollejas de pavo$t$, $t$Mollejas de pavo: órgano musculoso, cuenta como carne muscular. Molleja musculosa, cuenta como carne muscular. Naturalmente rica en proteínas.$t$),
  ('a0000002-0000-0000-0000-000000000002', $t$Espinazos de pollo$t$, $t$Espinazos de pollo con cartílago y restos de carne. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000004-0000-0000-0000-000000000001', $t$Hígado de pollo$t$, $t$Hígado de pollo: blando y fácil de conseguir, adecuado para perros pequeños. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('6fa17f82-6bfe-4071-b9ff-eaf134ded315', $t$Alas de pollo$t$, $t$Alas de pollo: hueso comestible fácil de digerir. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000002-0000-0000-0000-000000000001', $t$Cuellos de pollo$t$, $t$Cuellos de pollo blandos, hueso comestible ideal para perros pequeños y medianos. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('e7d8fcb4-ae47-46c1-89ec-f4324a565e4c', $t$Patas de pollo$t$, $t$Patas de pollo: fuente natural de glucosamina, premio popular. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000001-0000-0000-0000-000000000001', $t$Pechuga de pollo$t$, $t$Pechuga de pollo: carne blanca magra, base para perros sensibles. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('8086894d-8fb1-4590-bcf2-a88b9cede648', $t$Carcasas de pollo$t$, $t$Carcasas de pollo (esqueletos) tras deshuesar, con cartílago y restos de carne. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('a0000003-0000-0000-0000-000000000001', $t$Corazones de pollo$t$, $t$Corazones de pollo: corazones pequeños, fuente popular de taurina. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('a4b3be39-3cc1-4583-8cd7-7610b627ef70', $t$Muslo de pollo$t$, $t$Muslo de pollo: carne más oscura y jugosa. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('a824dddb-fd60-4bb3-870c-c2f9501de3ad', $t$Mollejas de pollo$t$, $t$Mollejas de pollo: musculosas, cuentan como carne muscular. Molleja musculosa, cuenta como carne muscular. Naturalmente rica en proteínas.$t$),
  ('7f31950d-8120-4e40-a229-5937b1731d79', $t$Coliflor$t$, $t$Coliflor: crucífera con vitamina C y folato. Mejor ligeramente cocida al vapor. Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('b6e5ab5e-544b-4e68-9490-0d1c1c79bee5', $t$Salmón$t$, $t$Salmón: pescado graso rico en omega-3. Congelado mín. 3 semanas por los parásitos. Pescado azul de mar, valiosa fuente de omega-3 y vitamina D. Incluir 1–2 veces por semana.$t$),
  ('a0000007-0000-0000-0000-000000000001', $t$Aceite de salmón$t$, $t$Aceite de salmón: fuente líquida de omega-3 para el pelaje y las articulaciones. Complemento de ácidos grasos omega-3 para el pelaje y las articulaciones. Unas gotas hasta unos ml al día según el tamaño del perro.$t$),
  ('0ebe106b-b2c4-4273-937a-3f34bdd94f3b', $t$Caballa$t$, $t$Caballa: pescado azul de mar con omega-3. Pescado azul de mar, valiosa fuente de omega-3 y vitamina D. Incluir 1–2 veces por semana.$t$),
  ('0943f697-a6db-4de0-baf6-62df039a0328', $t$Frambuesas$t$, $t$Frambuesas: bayas ricas en fibra y vitamina C. Solo pequeñas cantidades (contienen trazas de xilitol). Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('4d946245-2f63-4a2b-876b-53c526b7384b', $t$Cáscara de huevo molida$t$, $t$Cáscara de huevo molida: calcio puro para raciones sin hueso. Complemento de calcio para raciones sin hueso. Aprox. 1 g (½ cucharadita) por cada 500 g de carne.$t$),
  ('5d14b3ac-b118-4cb2-8a3a-0625ee499265', $t$Alga marina$t$, $t$Alga marina: fuente natural de yodo. Solo una pizca. Fuente natural de yodo para la tiroides. Solo una pizca: es fácil pasarse con el yodo.$t$),
  ('a0000005-0000-0000-0000-000000000001', $t$Zanahoria$t$, $t$Zanahoria: betacaroteno y fibra, también gusta cruda para roer. Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('1dc17ceb-c3cb-4328-af14-51131bc06525', $t$Moras$t$, $t$Moras: bayas oscuras con antioxidantes y fibra. Premio pequeño ideal. Fruta solo como premio ocasional en pequeñas cantidades por su contenido de azúcar.$t$),
  ('b2f1e6a4-7c3d-4b8e-9a12-5f7c9d0e1a23', $t$Puerro$t$, $t$Puerro: verdura del género Allium. ATENCIÓN: el puerro es tóxico para los perros (igual que la cebolla y el ajo): daña los glóbulos rojos y puede causar anemia hemolítica. No se recomienda darlo, ni siquiera cocinado.$t$),
  ('c815843e-9614-4cb4-bd19-df93b3f0726d', $t$Alga nori$t$, $t$Alga nori: alga marina con yodo y vitamina A, más suave que el kelp. Dar solo pequeñas cantidades. Fuente natural de yodo para la tiroides. Solo pequeñas cantidades: es fácil pasarse con el yodo.$t$),
  ('b1668561-d079-4ee0-a6b7-df9ccf3286dd', $t$Sardinas$t$, $t$Sardinas: pequeños pescados de mar, enteros con sus espinas. Pescado azul de mar, valiosa fuente de omega-3 y vitamina D. Incluir 1–2 veces por semana.$t$),
  ('d3c9da3b-e70e-42f7-b815-f019d1d97461', $t$Arenque$t$, $t$Arenque: pescado azul de mar, fuente de omega-3 y vitamina D. Pescado azul de mar, valiosa fuente de omega-3 y vitamina D. Incluir 1–2 veces por semana.$t$),
  ('a0000005-0000-0000-0000-000000000004', $t$Espinacas$t$, $t$Espinacas: verdura de hoja rica en hierro. Con moderación (oxalatos). Verdura: aprox. el 10 % de la ración. Para digerirla mejor, triturar o cocer ligeramente al vapor.$t$),
  ('8c40218d-0b9e-49c5-b376-34b3dd3e58bf', $t$Carne de corzo$t$, $t$Carne de corzo: caza magra y delicada. Base de la ración: constituye el 50–70 % de la parte cárnica. Si la caza no procede de una fuente verificada (p. ej. del supermercado), mejor cocerla.$t$),
  ('4258ea8a-cbdb-4349-9b8b-c5714717f8f0', $t$Hígado de ternera$t$, $t$Hígado de ternera: más delicado y ligero que el de vacuno adulto. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('f1085f36-49e8-4bf6-93e6-206687616f05', $t$Carne muscular de ternera$t$, $t$Carne muscular de ternera: carne magra y delicada. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('17da90b5-de38-41bd-bbe7-e0a4efb2ec67', $t$Requesón$t$, $t$Requesón: proteína ligera y calcio. Complemento lácteo: solo en pequeñas cantidades, algunos perros toleran mal la lactosa. Fuente de proteínas y calcio.$t$),
  ('a0000007-0000-0000-0000-000000000002', $t$Huevo$t$, $t$Huevo: proteína completa; con cáscara, también fuente de calcio. Huevo entero con cáscara: proteína completa y calcio. 2–3 veces por semana según el tamaño del perro.$t$),
  ('6dff6fc2-dfdd-40cb-9de2-4ac3864885c3', $t$Diafragma de cerdo (entraña)$t$, $t$Diafragma de cerdo: músculo fino del diafragma, carne muscular sabrosa. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('bb8a8f3d-c79d-4ee3-a03b-40943c8e46bb', $t$Cabeza de cerdo$t$, $t$Cabeza de cerdo: carne, cartílago y hueso juntos. Hueso de carga más duro: más para roer que para comer. SIEMPRE crudo, vigila el desgaste dental.$t$),
  ('5cfdf04b-cfba-4cd7-b52e-0dcb6a3844f1', $t$Hígado de cerdo$t$, $t$Hígado de cerdo: fuente de hígado asequible, sabor intenso. El órgano más importante del BARF, extremadamente rico en vitamina A, cobre y hierro. Máx. 5 % de la ración, si no hay riesgo de sobredosis de vitamina A.$t$),
  ('af918a13-86cd-4a50-bac8-88b550b4a5a9', $t$Aguja de cerdo$t$, $t$Aguja de cerdo: pieza más jugosa y veteada. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('835bf3b4-0ed7-41f5-a780-0acaef4c3590', $t$Pierna de cerdo$t$, $t$Pierna de cerdo: pieza trasera más magra. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('59676165-74e0-4e97-993e-2ce4aa470717', $t$Carrilleras de cerdo$t$, $t$Carrilleras de cerdo: músculo de trabajo jugoso. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('80f5f491-4091-4b6f-8a93-b30db86cc90a', $t$Hueso de caña de cerdo$t$, $t$Hueso de caña de cerdo: hueso de carga duro, para roer. Hueso de carga más duro: más para roer que para comer. SIEMPRE crudo, vigila el desgaste dental.$t$),
  ('754de29a-cd26-406f-86cd-2c5a82d8ea5d', $t$Solomillo de cerdo$t$, $t$Solomillo de cerdo: la pieza más magra del cerdo. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('0e056f3b-1cb6-4453-bf8d-1e6029246a46', $t$Lomo de cerdo (chuleta)$t$, $t$Lomo de cerdo (chuleta): carne magra del lomo. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('c6d2374c-71f7-4f34-a816-f259c96e7448', $t$Paleta de cerdo$t$, $t$Paleta de cerdo: pieza de grasa media. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('1588c11d-3a4d-4ee7-bdb8-13999488b15c', $t$Bazo de cerdo$t$, $t$Bazo de cerdo: órgano rico en hierro. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('381853bc-32bc-4e3c-842c-f588fd652fd7', $t$Páncreas de cerdo$t$, $t$Páncreas de cerdo: fuente de enzimas digestivas. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('d5b2b7e3-34e8-4846-812b-da1ea3131e01', $t$Carne muscular de cerdo$t$, $t$Carne muscular de cerdo: carne de cerdo en general. Siempre bien congelada (Aujeszky). Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('cc786e81-634e-4aba-acf1-de134cd83850', $t$Costillas de cerdo$t$, $t$Costillas de cerdo: hueso comestible carnoso. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('4224fc51-d21a-4c08-ad09-2e20d29f6bec', $t$Codillo de cerdo$t$, $t$Codillo de cerdo: hueso de carga más duro con carne. Hueso de carga más duro: más para roer que para comer. SIEMPRE crudo, vigila el desgaste dental.$t$),
  ('876caa4e-47a0-4ac0-b524-2f5d72aacb97', $t$Riñones de cerdo$t$, $t$Riñones de cerdo: órgano secretor asequible. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('01ffd839-64be-4c08-b7e6-05e49bbc9961', $t$Manitas de cerdo$t$, $t$Manitas de cerdo: piel, cartílago y hueso, fuente de colágeno. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('79930f0f-64d7-4f43-a080-8b0f7e2dbd8f', $t$Pulmón de cerdo$t$, $t$Pulmón de cerdo: órgano ligero y bajo en grasa. Dar como complemento de la parte cárnica; también es popular deshidratado como premio.$t$),
  ('ef60c485-97b6-4285-b971-92663e5dfd57', $t$Manteca de cerdo$t$, $t$Manteca de cerdo: grasa animal pura, energía concentrada. Grasa pura: fuente concentrada de energía. Usar con moderación, sobre todo en perros activos o desnutridos.$t$),
  ('b5129d74-6082-416d-a926-d3512ebd7381', $t$Corazón de cerdo$t$, $t$Corazón de cerdo: órgano muscular con taurina. Órgano muscular rico en taurina: cuenta como carne muscular, no como víscera. Hasta el 10–15 % de la ración.$t$),
  ('4746ff20-9eb2-49c5-a856-bf10ed381957', $t$Orejas de cerdo$t$, $t$Orejas de cerdo: premio cartilaginoso para roer. Parte cartilaginosa: fuente natural de glucosamina y condroitina para las articulaciones. Premio masticable muy popular.$t$),
  ('b50e8776-88e4-41b9-b0bd-8898b0de24a7', $t$Timo de cerdo (mollejas)$t$, $t$Timo de cerdo: órgano secretor glandular de sabor suave. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('3b5e40a9-b3d2-438d-b49f-bb8bede65120', $t$Panceta de cerdo$t$, $t$Panceta de cerdo: pieza muy grasa y energética. Con moderación. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('6c21434d-854d-405e-831b-54fe8eb33d95', $t$Lengua de cerdo$t$, $t$Lengua de cerdo: carne muscular más grasa. Base de la ración: constituye el 50–70 % de la parte cárnica.$t$),
  ('e7b543db-0607-4c85-b4a5-eb47289b8784', $t$Sesos de cerdo$t$, $t$Sesos de cerdo: ricos en grasas y DHA. Órgano secretor (vísceras). Junto con el hígado constituye aprox. el 10 % de la ración, de la cual los órganos distintos del hígado ~5 %.$t$),
  ('c3268866-3fc0-45ad-86d3-546ad12c8d3f', $t$Rabo de cerdo$t$, $t$Rabo de cerdo: hueso comestible graso con cartílago. Hueso blando comestible: fuente de calcio. Constituye aprox. el 10–15 % de la ración. SIEMPRE crudo, nunca cocido (los huesos cocidos se astillan).$t$),
  ('6e8b6695-b121-4fa1-b17e-9fce79b614d1', $t$Estómago de cerdo$t$, $t$Estómago de cerdo: órgano musculoso, apoya la digestión. Estómago (callos): verde y sin lavar es excelente para la digestión y el microbioma. Cuenta como carne muscular.$t$),
  ('914c4da0-4e64-4384-b334-59fdbf8516db', $t$Carne de ciervo (venado)$t$, $t$Carne de ciervo (venado): carne oscura y magra. Base de la ración: constituye el 50–70 % de la parte cárnica. Si la caza no procede de una fuente verificada (p. ej. del supermercado), mejor cocerla.$t$)
) as v(food_id, name, description)
where not exists (
  select 1 from public.food_translations t where t.food_id = v.food_id::uuid and t.locale = 'es'
);
